#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEdusdkClient: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = EdusdkClient

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> EdusdkClient {
        return EdusdkClient(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: EdusdkClient) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EdusdkClient {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: EdusdkClient, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEdusdkClient_lift(_ pointer: UnsafeMutableRawPointer) throws -> EdusdkClient {
    return try FfiConverterTypeEdusdkClient.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEdusdkClient_lower(_ value: EdusdkClient) -> UnsafeMutableRawPointer {
    return FfiConverterTypeEdusdkClient.lower(value)
}




public struct BackendSnapshot {
    public var classroomId: String?
    public var classPhase: MobileClassPhase
    public var lifecycleStatus: MobileClassroomLifecycleStatus
    public var localUserId: String?
    public var onStageUserIds: [String]
    public var raisedHandUserIds: [String]
    /**
     * 从 join room_metadata.classroom.name 解析
     */
    public var classroomTitle: String?
    /**
     * 进行中且本人未上台：不进 RTC，改拉台上直播流。
     */
    public var needLive: Bool
    public var members: [ClassroomMemberSnapshot]
    public var memberCount: UInt32
    public var membersNextCursor: String?
    public var toolsJson: String?
    /**
     * 台下该播哪几路。台上为空，画面走 RTC
     */
    public var liveStreams: [LiveStreamSnapshot]
    /**
     * 与 `classroom.live_relay_changed` 对齐的集合版本
     */
    public var liveRelayVersion: Int64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(classroomId: String?, classPhase: MobileClassPhase, lifecycleStatus: MobileClassroomLifecycleStatus, localUserId: String?, onStageUserIds: [String], raisedHandUserIds: [String], 
        /**
         * 从 join room_metadata.classroom.name 解析
         */classroomTitle: String?, 
        /**
         * 进行中且本人未上台：不进 RTC，改拉台上直播流。
         */needLive: Bool, members: [ClassroomMemberSnapshot], memberCount: UInt32, membersNextCursor: String?, toolsJson: String?, 
        /**
         * 台下该播哪几路。台上为空，画面走 RTC
         */liveStreams: [LiveStreamSnapshot], 
        /**
         * 与 `classroom.live_relay_changed` 对齐的集合版本
         */liveRelayVersion: Int64) {
        self.classroomId = classroomId
        self.classPhase = classPhase
        self.lifecycleStatus = lifecycleStatus
        self.localUserId = localUserId
        self.onStageUserIds = onStageUserIds
        self.raisedHandUserIds = raisedHandUserIds
        self.classroomTitle = classroomTitle
        self.needLive = needLive
        self.members = members
        self.memberCount = memberCount
        self.membersNextCursor = membersNextCursor
        self.toolsJson = toolsJson
        self.liveStreams = liveStreams
        self.liveRelayVersion = liveRelayVersion
    }
}

#if compiler(>=6)
extension BackendSnapshot: Sendable {}
#endif


extension BackendSnapshot: Equatable, Hashable {
    public static func ==(lhs: BackendSnapshot, rhs: BackendSnapshot) -> Bool {
        if lhs.classroomId != rhs.classroomId {
            return false
        }
        if lhs.classPhase != rhs.classPhase {
            return false
        }
        if lhs.lifecycleStatus != rhs.lifecycleStatus {
            return false
        }
        if lhs.localUserId != rhs.localUserId {
            return false
        }
        if lhs.onStageUserIds != rhs.onStageUserIds {
            return false
        }
        if lhs.raisedHandUserIds != rhs.raisedHandUserIds {
            return false
        }
        if lhs.classroomTitle != rhs.classroomTitle {
            return false
        }
        if lhs.needLive != rhs.needLive {
            return false
        }
        if lhs.members != rhs.members {
            return false
        }
        if lhs.memberCount != rhs.memberCount {
            return false
        }
        if lhs.membersNextCursor != rhs.membersNextCursor {
            return false
        }
        if lhs.toolsJson != rhs.toolsJson {
            return false
        }
        if lhs.liveStreams != rhs.liveStreams {
            return false
        }
        if lhs.liveRelayVersion != rhs.liveRelayVersion {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(classroomId)
        hasher.combine(classPhase)
        hasher.combine(lifecycleStatus)
        hasher.combine(localUserId)
        hasher.combine(onStageUserIds)
        hasher.combine(raisedHandUserIds)
        hasher.combine(classroomTitle)
        hasher.combine(needLive)
        hasher.combine(members)
        hasher.combine(memberCount)
        hasher.combine(membersNextCursor)
        hasher.combine(toolsJson)
        hasher.combine(liveStreams)
        hasher.combine(liveRelayVersion)
    }
}



